    "id": "art-movidesk-558736",
    "code": "CC-114",
    "title": "Relatório de Cobertura de Dados Open Finance",
    "slug": "relatorio-de-cobertura-de-dados-open-finance",
    "categoryId": "cat-7",
    "categoryName": "Open Finance",
    "authorId": "usr-fulvio",
